local services = tool('list_services')
local counts = {}
for _, s in ipairs(services) do
  local r = tool('search_logs', { service = s, level = 'ERROR', page = 1 })
  counts[s] = { total_errors = r.total_items, total_pages = r.total_pages }
end
return { services = services, counts = counts }

